import{_ as a,o as t,c as r,ae as i}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"多帳本功能說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/04-multi-ledger-guide.md","filePath":"v1/zh-HK/guide/04-multi-ledger-guide.md"}'),l={name:"v1/zh-HK/guide/04-multi-ledger-guide.md"};function o(d,e,n,s,h,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="多帳本功能說明" tabindex="-1">多帳本功能說明 <a class="header-anchor" href="#多帳本功能說明" aria-label="Permalink to &quot;多帳本功能說明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>你可以建立多個帳本，將不同用途的收支分開管理。每個帳本可獨立設定名稱、貨幣與分類。</p><h2 id="🚀-建立與切換" tabindex="-1">🚀 建立與切換 <a class="header-anchor" href="#🚀-建立與切換" aria-label="Permalink to &quot;🚀 建立與切換&quot;">​</a></h2><ul><li>建立：設定 → 帳本管理 → 右上角 <code>+</code> → 填寫資料 → 保存</li><li>切換：在帳本管理列表點選帳本卡片</li></ul><h2 id="🗑️-刪除帳本" tabindex="-1">🗑️ 刪除帳本 <a class="header-anchor" href="#🗑️-刪除帳本" aria-label="Permalink to &quot;🗑️ 刪除帳本&quot;">​</a></h2><p>在帳本詳情頁點「刪除帳本」。</p><p>⚠️ 刪除後會移除該帳本資料；如已開啟雲端同步，後續同步也會從雲端刪除。此操作不可在 App 內復原，請謹慎。</p><hr><p><strong>最後更新</strong>：2026 年 1 月</p>',10)])])}const p=a(l,[["render",o]]);export{_ as __pageData,p as default};
